-- Removes ONLY the objects LifeSphere's migrations created: 86 tables, 63 enum types, and the schemas auth / pgboss / drizzle.
-- Run in the Neon SQL editor against the SHARED database (neondb), AFTER LifeSphere works on its own database.
-- Step 1 is read-only. Step 2 runs in a transaction: check the result, then COMMIT (or ROLLBACK).

-- STEP 1a: preview. Expect 86 rows, all LifeSphere tables created today (approx_rows near 0 apart from seed data).
SELECT n.nspname AS schema, c.relname AS table_name, c.reltuples::bigint AS approx_rows
FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace
WHERE c.relkind = 'r' AND (n.nspname || '.' || c.relname) = ANY (ARRAY['auth.mfa_factors', 'auth.otp_challenges', 'auth.recovery_codes', 'auth.sessions', 'public.access_grants', 'public.ai_conversations', 'public.ai_eval_cases', 'public.ai_eval_runs', 'public.ai_feedback', 'public.ai_messages', 'public.alert_deliveries', 'public.app_config', 'public.attachments', 'public.audit_events', 'public.bookmarks', 'public.calendar_events', 'public.case_attachments', 'public.check_in_escalation_contacts', 'public.check_in_events', 'public.check_in_schedules', 'public.civic_issues', 'public.comments', 'public.community_groups', 'public.complaint_drafts', 'public.consent_records', 'public.consumer_case_events', 'public.consumer_cases', 'public.contact_invitations', 'public.content_reports', 'public.content_snapshots', 'public.emergency_contact_preferences', 'public.event_attendees', 'public.family_announcements', 'public.group_invitations', 'public.group_memberships', 'public.help_request_recipients', 'public.help_requests', 'public.home_inventory_items', 'public.household_budgets', 'public.household_invitations', 'public.household_members', 'public.households', 'public.idempotency_keys', 'public.knowledge_articles', 'public.knowledge_chunks', 'public.knowledge_sources', 'public.localities', 'public.maintenance_records', 'public.maintenance_schedules', 'public.moderation_actions', 'public.moderation_appeals', 'public.notification_devices', 'public.notification_jobs', 'public.notification_preferences', 'public.notifications', 'public.official_channels', 'public.plans', 'public.post_attachments', 'public.posts', 'public.privacy_requests', 'public.provider_members', 'public.provider_reviews', 'public.provider_service_areas', 'public.provider_services', 'public.provider_verification_records', 'public.purchases', 'public.reactions', 'public.reminders', 'public.service_categories', 'public.service_providers', 'public.service_request_events', 'public.service_requests', 'public.shopping_list_items', 'public.shopping_lists', 'public.staff_roles', 'public.subscriptions', 'public.task_assignments', 'public.task_attachments', 'public.task_categories', 'public.tasks', 'public.trusted_contacts', 'public.user_blocks', 'public.user_preferences', 'public.user_profiles', 'public.user_sanctions', 'public.users'])
ORDER BY 1, 2;

-- STEP 1b: confirm no other app uses these schemas.
SELECT table_schema, count(*) AS tables FROM information_schema.tables
WHERE table_schema IN ('auth', 'pgboss', 'drizzle') GROUP BY 1;

-- STEP 2: remove (transaction).
BEGIN;
DROP TABLE IF EXISTS auth.mfa_factors, auth.otp_challenges, auth.recovery_codes, auth.sessions, public.access_grants, public.ai_conversations, public.ai_eval_cases, public.ai_eval_runs, public.ai_feedback, public.ai_messages, public.alert_deliveries, public.app_config, public.attachments, public.audit_events, public.bookmarks, public.calendar_events, public.case_attachments, public.check_in_escalation_contacts, public.check_in_events, public.check_in_schedules, public.civic_issues, public.comments, public.community_groups, public.complaint_drafts, public.consent_records, public.consumer_case_events, public.consumer_cases, public.contact_invitations, public.content_reports, public.content_snapshots, public.emergency_contact_preferences, public.event_attendees, public.family_announcements, public.group_invitations, public.group_memberships, public.help_request_recipients, public.help_requests, public.home_inventory_items, public.household_budgets, public.household_invitations, public.household_members, public.households, public.idempotency_keys, public.knowledge_articles, public.knowledge_chunks, public.knowledge_sources, public.localities, public.maintenance_records, public.maintenance_schedules, public.moderation_actions, public.moderation_appeals, public.notification_devices, public.notification_jobs, public.notification_preferences, public.notifications, public.official_channels, public.plans, public.post_attachments, public.posts, public.privacy_requests, public.provider_members, public.provider_reviews, public.provider_service_areas, public.provider_services, public.provider_verification_records, public.purchases, public.reactions, public.reminders, public.service_categories, public.service_providers, public.service_request_events, public.service_requests, public.shopping_list_items, public.shopping_lists, public.staff_roles, public.subscriptions, public.task_assignments, public.task_attachments, public.task_categories, public.tasks, public.trusted_contacts, public.user_blocks, public.user_preferences, public.user_profiles, public.user_sanctions, public.users CASCADE;
DROP TYPE IF EXISTS public.actor_type, public.ai_role, public.appeal_status, public.article_status, public.assignment_status, public.attachment_purpose, public.attachment_status, public.attendee_status, public.calendar_event_kind, public.case_event_kind, public.check_in_event_state, public.check_in_kind, public.civic_category, public.civic_status, public.consumer_case_status, public.content_status, public.device_platform, public.draft_source, public.feedback_rating, public.grant_scope, public.grant_status, public.group_role, public.group_status, public.group_visibility, public.help_request_kind, public.help_request_status, public.household_role, public.invitation_status, public.lock_screen_detail, public.membership_status, public.moderation_action_kind, public.notification_category, public.notification_channel, public.notification_job_status, public.official_channel_kind, public.otp_channel, public.otp_purpose, public.post_kind, public.posting_policy, public.privacy_request_status, public.privacy_request_type, public.provider_member_role, public.provider_status, public.provider_type, public.reaction_kind, public.reminder_status, public.report_reason, public.report_status, public.report_target_type, public.sanction_kind, public.service_request_status, public.source_kind, public.staff_role, public.subscription_status, public.subscription_subject, public.task_priority, public.task_status, public.task_visibility, public.theme_preference, public.user_status, public.verification_check_type, public.verification_level, public.verification_status CASCADE;
DROP SCHEMA IF EXISTS pgboss CASCADE;   -- LifeSphere job queue
DROP SCHEMA IF EXISTS drizzle CASCADE;  -- LifeSphere migration history
DROP SCHEMA IF EXISTS auth;             -- no CASCADE: fails safely if anything else is in "auth"
-- Then run ONE of:
-- COMMIT;
-- ROLLBACK;
